<div class="table-wrap"><table class="table"><thead><tr><th>Network</th><th>Programma</th><th>Stato</th><th>Ultimo sync</th></tr></thead><tbody><?php foreach ($programs as $program): ?><tr><td><?php echo e($program['network']); ?></td><td><?php echo e($program['program']); ?></td><td><span class="tag <?php echo strtolower($program['status']) === 'paused' ? 'status-scheduled' : 'status-active'; ?>"><?php echo e($program['status']); ?></span></td><td><?php echo e($program['last_sync']); ?></td></tr><?php endforeach; ?></tbody></table></div>
